const fs = require('fs');
const data = JSON.parse(fs.readFileSync('/app/benchmark/source_data.json', 'utf8'));

const regions = ['North America', 'Europe', 'Asia-Pacific', 'Latin America'];
const years = Array.from({ length: 10 }, (_, i) => 2015 + i);
const yearsNeo = Array.from({ length: 9 }, (_, i) => 2016 + i);
const regionColors = {
  'North America': '#2563eb',
  'Europe': '#7c3aed',
  'Asia-Pacific': '#0f766e',
  'Latin America': '#d97706'
};
const indicatorColors = {
  payment: '#0f766e',
  licenses: '#c08403',
  branches: '#dc2626',
  neobank: '#2563eb'
};

function byRegion(dataset, field) {
  const map = new Map();
  for (const row of data[dataset].data) {
    if (!map.has(row.region)) map.set(row.region, new Map());
    map.get(row.region).set(row.year, row[field]);
  }
  return map;
}
const payment = byRegion('digital_payment_penetration', 'penetration_pct');
const branches = byRegion('traditional_bank_branches', 'branches_k');
const neobank = byRegion('neobank_users', 'users_m');
const licenses = byRegion('digital_bank_licenses', 'cumulative_licenses');

function sumFor(map, year) { return regions.reduce((sum, r) => sum + (map.get(r).get(year) || 0), 0); }
function avgFor(map, year) { return sumFor(map, year) / regions.length; }

const global = years.map(year => ({
  year,
  paymentPct: avgFor(payment, year),
  branchesK: sumFor(branches, year),
  licenses: sumFor(licenses, year)
}));
const globalIndex = global.map((row, i) => ({
  year: row.year,
  payment: row.paymentPct / global[0].paymentPct * 100,
  branches: row.branchesK / global[0].branchesK * 100,
  licenses: row.licenses / global[0].licenses * 100
}));

const closures = years.slice(1).map(year => {
  const prev = year - 1;
  const values = regions.map(region => ({
    region,
    value: +(branches.get(region).get(prev) - branches.get(region).get(year)).toFixed(1)
  }));
  return { year, values, total: values.reduce((s, d) => s + d.value, 0) };
});

const approvals = years.slice(1).map(year => {
  const prev = year - 1;
  const values = regions.map(region => ({
    region,
    value: licenses.get(region).get(year) - licenses.get(region).get(prev)
  }));
  return { year, values, total: values.reduce((s, d) => s + d.value, 0) };
});

const neoSeries = regions.map(region => ({
  region,
  values: yearsNeo.map(year => ({ year, value: neobank.get(region).get(year) }))
}));

const fmt1 = n => Math.round(n * 10) / 10;
const totalClosure2019 = closures.find(d => d.year === 2019).total;
const totalClosure2020 = closures.find(d => d.year === 2020).total;
const license2021 = approvals.find(d => d.year === 2021).total;
const payment2024 = global.at(-1).paymentPct;
const branchDecline = (1 - global.at(-1).branchesK / global[0].branchesK) * 100;
const totalNeo2024 = regions.reduce((s, r) => s + neobank.get(r).get(2024), 0);

function htmlEscape(s) { return String(s).replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }

const scriptData = JSON.stringify({
  regions, years, yearsNeo, regionColors, indicatorColors, globalIndex, closures, approvals, neoSeries,
  global, metrics: { totalClosure2019, totalClosure2020, license2021, payment2024, branchDecline, totalNeo2024 }
});

